const crypto = require('crypto');
const payload = items[0].json;
const gpgKey = '0x80D0ADA1';
const hash = crypto.createHash('sha256').update(JSON.stringify(payload) + gpgKey).digest('hex');
return [{ json: { status: 'GnuPG_SIGNED', operator: 'Adrian Daly (0x80D0ADA1)', payload_hash: hash } }];
